import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a8795d');
scene.fog = new THREE.FogExp2('#aa8064', 0.0085);
const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.1, 260);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

const mat = (color, roughness = 0.88, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const mats = {
  sand: mat('#bca17d'), road: mat('#827766'), stone: mat('#d0b38b'), wall: mat('#cfb38a'),
  wallLight: mat('#dfc69e'), trim: mat('#9e7755'), dark: mat('#473f36'), wood: mat('#65483a'),
  teal: mat('#327b78'), blue: mat('#416b75'), red: mat('#a9513d'), gold: mat('#d7b36d', .38, { metalness: .34 }),
  cloth: mat('#273f3e'), robe: mat('#344b47'), skin: mat('#b77e5a'), black: mat('#202c2b'),
  leaf: mat('#526548'), leaf2: mat('#72804f'), water: mat('#567f7c', .2, { metalness: .3 }),
  emissive: mat('#ffbf65', .3, { emissive: '#ff9d3d', emissiveIntensity: 2.4 }),
};
const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const sphereGeo = new THREE.SphereGeometry(1, 16, 12);
const cylinderGeo = new THREE.CylinderGeometry(1, 1, 1, 12);
const colliders = [];
const interactives = [];
const guards = [];
const tempV = new THREE.Vector3();
const clamp = THREE.MathUtils.clamp;

function box(parent, x, y, z, w, h, d, material, cast = true, receive = true) {
  const mesh = new THREE.Mesh(boxGeo, material);
  mesh.position.set(x, y + h / 2, z); mesh.scale.set(w, h, d);
  mesh.castShadow = cast; mesh.receiveShadow = receive; parent.add(mesh);
  return mesh;
}
function sphere(parent, x, y, z, r, material, scaleY = 1) {
  const mesh = new THREE.Mesh(sphereGeo, material); mesh.position.set(x, y, z); mesh.scale.set(r, r * scaleY, r); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function cylinder(parent, x, y, z, radius, height, material, sides = 12) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius * .84, radius, height, sides), material);
  mesh.position.set(x, y + height / 2, z); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function addCollider(x, z, w, d, h) { colliders.push({ x, z, w, d, h }); }
function makeGroup(x, z) { const g = new THREE.Group(); g.position.set(x, 0, z); scene.add(g); return g; }

// Sunset sky, warm directional light, and a quiet moon over the old quarter.
scene.add(new THREE.HemisphereLight('#f4d8b0', '#48433b', 1.55));
const sun = new THREE.DirectionalLight('#ffd29a', 3.2);
sun.position.set(-42, 62, 34); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -100; sun.shadow.camera.right = 100; sun.shadow.camera.top = 100; sun.shadow.camera.bottom = -100;
sun.shadow.bias = -.00035; sun.shadow.normalBias = .025; scene.add(sun);
const fill = new THREE.DirectionalLight('#92b7b2', .75); fill.position.set(45, 28, -55); scene.add(fill);
const sunDisc = new THREE.Mesh(new THREE.SphereGeometry(7, 24, 16), new THREE.MeshBasicMaterial({ color: '#ffc783' }));
sunDisc.position.set(-75, 43, -100); scene.add(sunDisc);

// Ground and irregular stone lanes.
const ground = new THREE.Mesh(new THREE.PlaneGeometry(230, 230), mats.sand);
ground.rotation.x = -Math.PI / 2; ground.position.y = -.12; ground.receiveShadow = true; scene.add(ground);
for (let i = -4; i <= 4; i++) {
  const laneX = new THREE.Mesh(new THREE.PlaneGeometry(6.7, 190), mats.road);
  laneX.rotation.x = -Math.PI / 2; laneX.position.set(i * 22, -.105, 0); laneX.receiveShadow = true; scene.add(laneX);
  const laneZ = new THREE.Mesh(new THREE.PlaneGeometry(190, 6.7), mats.road);
  laneZ.rotation.x = -Math.PI / 2; laneZ.position.set(0, -.103, i * 22); laneZ.receiveShadow = true; scene.add(laneZ);
}
// Tiny hand-set stone flecks keep the ground from reading as a flat plane.
let seed = 93741;
function rand() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }
for (let i = 0; i < 780; i++) {
  const x = rand() * 205 - 102.5, z = rand() * 205 - 102.5;
  if (Math.abs(x % 22) < 3.9 || Math.abs(z % 22) < 3.9) continue;
  const pebble = box(scene, x, -.015, z, .13 + rand() * .28, .025, .09 + rand() * .2, rand() > .5 ? mats.trim : mats.wallLight, false, false);
  pebble.rotation.y = rand() * Math.PI;
}

function archPanel(parent, x, y, z, width, height, material, facing = 'front') {
  const panel = new THREE.Mesh(new THREE.CircleGeometry(width / 2, 20, 0, Math.PI), material);
  panel.position.set(x, y, z);
  if (facing === 'front') panel.rotation.set(0, 0, 0);
  else panel.rotation.set(0, Math.PI / 2, 0);
  parent.add(panel);
}
function makeBuilding(x, z, w, d, h, variant = 0) {
  const g = makeGroup(x, z), wallMat = [mats.wall, mats.wallLight, mats.stone, mat('#c5a77e')][variant % 4];
  box(g, 0, 0, 0, w, h, d, wallMat);
  box(g, 0, h, 0, w + .45, .35, d + .45, mats.trim);
  box(g, 0, h + .28, 0, w + .85, .18, d + .85, mats.wallLight);
  box(g, 0, h + .4, -d / 2 + .12, w + .65, .9, .22, mats.wall);
  box(g, 0, h + .4, d / 2 - .12, w + .65, .9, .22, mats.wall);
  box(g, -w / 2 + .12, h + .4, 0, .22, .9, d, mats.wall);
  box(g, w / 2 - .12, h + .4, 0, .22, .9, d, mats.wall);
  // Recessed doors, lintels, painted window frames, and timber beams.
  for (const side of [-1, 1]) {
    const doorX = side * w * .27;
    box(g, doorX, 0, d / 2 + .025, w * .16, h * .53, .07, mats.wood);
    box(g, doorX, h * .53, d / 2 + .07, w * .2, .14, .12, mats.gold);
    for (const wx of [-w * .27, w * .27]) {
      box(g, wx, h * .68, d / 2 + .045, w * .115, h * .14, .08, mats.dark);
      box(g, wx, h * .68, d / 2 + .1, .07, h * .18, .07, mats.trim);
      box(g, wx, h * .68, d / 2 + .1, w * .14, .06, .08, mats.wallLight);
    }
  }
  // Roof vents and a small sunshade; high-contrast color brings the market to life.
  if (variant % 3 === 0) {
    box(g, 0, h + .55, 0, w * .32, .35, d * .28, mats.trim);
    const dome = new THREE.Mesh(new THREE.SphereGeometry(w * .21, 20, 12, 0, Math.PI * 2, 0, Math.PI / 2), variant === 0 ? mats.teal : mats.blue);
    dome.position.set(0, h + .7, 0); dome.castShadow = true; g.add(dome);
  } else {
    box(g, 0, h + .2, d / 2 + .65, w * .62, .13, 1.3, variant % 2 ? mats.red : mats.teal);
    for (let aw = -2; aw <= 2; aw++) box(g, aw * w * .12, h * .18, d / 2 + 1.05, .06, h * .3, .06, mats.wood);
  }
  // Narrow roofline crenellations.
  for (let px = -w / 2 + .8; px < w / 2; px += 1.4) {
    box(g, px, h + .56, -d / 2 + .1, .27, .38, .32, mats.wallLight, false);
    box(g, px, h + .56, d / 2 - .1, .27, .38, .32, mats.wallLight, false);
  }
  addCollider(x, z, w + .3, d + .3, h + .8);
  return g;
}

// Dense, walkable quarter: blocks frame streets instead of sealing them off.
const reserved = [[0, 0, 27], [-27, 11, 12], [27, -11, 13], [-11, -44, 13], [0, -77, 17], [-50, 50, 10]];
for (let gx = -3; gx <= 3; gx++) for (let gz = -3; gz <= 3; gz++) {
  for (const ox of [-4.3, 4.3]) for (const oz of [-4.25, 4.25]) {
    const x = gx * 22 + ox, z = gz * 22 + oz;
    if (reserved.some(([rx, rz, r]) => Math.hypot(x - rx, z - rz) < r)) continue;
    const w = 9.4 + rand() * 2.6, d = 9.5 + rand() * 2.4, h = 5.2 + rand() * 3.9;
    makeBuilding(x, z, w, d, h, Math.floor(rand() * 5));
  }
}

// Courtyard fountain and the minaret that marks the final memory.
const fountain = makeGroup(0, 0);
cylinder(fountain, 0, 0, 0, 4.1, .55, mats.trim, 24);
cylinder(fountain, 0, .52, 0, 3.55, .28, mats.wallLight, 24);
cylinder(fountain, 0, .8, 0, 2.45, .22, mats.water, 24);
cylinder(fountain, 0, 1, 0, .42, .55, mats.trim, 16);
sphere(fountain, 0, 1.8, 0, .36, mats.water, 1.3);
for (let i = 0; i < 8; i++) {
  const a = i * Math.PI / 4, x = Math.cos(a) * 4.45, z = Math.sin(a) * 4.45;
  cylinder(fountain, x, 0, z, .13, 1.25, mats.gold, 8);
  sphere(fountain, x, 1.26, z, .22, mats.emissive, 1.35);
}

function makeMinaret() {
  const g = makeGroup(0, -77);
  cylinder(g, 0, 0, 0, 4.6, 20, mats.wallLight, 16);
  cylinder(g, 0, 15, 0, 5.2, 1.1, mats.trim, 16);
  cylinder(g, 0, 16.1, 0, 3.8, 5.8, mats.wall, 16);
  cylinder(g, 0, 20, 0, 4.35, .65, mats.gold, 16);
  cylinder(g, 0, 21, 0, 2.9, 5.2, mats.teal, 16);
  const roof = new THREE.Mesh(new THREE.ConeGeometry(3.2, 6, 16), mats.trim); roof.position.set(0, 28.1, 0); roof.castShadow = true; g.add(roof);
  cylinder(g, 0, 31.2, 0, .16, 1.7, mats.gold, 8);
  sphere(g, 0, 32.2, 0, .28, mats.gold, 1.5);
  for (let y = 3; y < 15; y += 3) for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4, wx = Math.cos(a) * 4.48, wz = Math.sin(a) * 4.48;
    box(g, wx, y, wz, .48, 1.15, .16, mats.dark);
    sphere(g, wx, y + .62, wz, .25, mats.gold, 1.3);
  }
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI / 2, x = Math.cos(a) * 6.1, z = Math.sin(a) * 6.1;
    box(g, x, 0, z, .5, 1.25, .5, mats.trim);
    sphere(g, x, 1.3, z, .25, mats.emissive);
  }
  addCollider(0, -77, 9.5, 9.5, 33);
}
makeMinaret();

// A handful of courtyard palms, date baskets, and warm hanging lamps.
function makePalm(x, z, scale = 1) {
  const g = makeGroup(x, z);
  cylinder(g, 0, 0, 0, .22 * scale, 4.3 * scale, mats.trim, 8);
  sphere(g, 0, 4.35 * scale, 0, .56 * scale, mats.leaf, .55);
  for (let i = 0; i < 7; i++) {
    const a = i * Math.PI * 2 / 7, frond = box(g, Math.cos(a) * .95 * scale, 4.2 * scale, Math.sin(a) * .95 * scale, 1.85 * scale, .12 * scale, .3 * scale, i % 2 ? mats.leaf : mats.leaf2, false);
    frond.rotation.y = -a; frond.rotation.z = -.25;
  }
}
for (const [x, z] of [[-12, 12], [12, 12], [-12, -12], [12, -12], [-32, 18], [32, -21], [-17, -48], [7, -68]]) makePalm(x, z, .82 + rand() * .25);

function makeLamp(x, z) {
  const g = makeGroup(x, z);
  cylinder(g, 0, 0, 0, .09, 3.2, mats.dark, 8);
  box(g, 0, 3.15, 0, .55, .1, .55, mats.gold);
  const flame = sphere(g, 0, 2.68, 0, .18, mats.emissive, 1.5);
  const light = new THREE.PointLight('#ffb85f', 8, 10, 2); light.position.set(x, 2.7, z); scene.add(light);
  return flame;
}
for (const [x, z] of [[-3.5, 13], [3.5, 13], [-3.5, -13], [3.5, -13], [-25, 0], [25, 0], [0, -47], [0, -69], [-43, 22], [43, -22]]) makeLamp(x, z);

function makeStall(x, z, color, angle = 0) {
  const g = makeGroup(x, z); g.rotation.y = angle;
  box(g, 0, .65, 0, 4.5, 1.3, 2.2, mats.wood);
  box(g, 0, 1.42, 0, 4.8, .14, 2.6, mats.gold);
  for (const px of [-2.1, 2.1]) for (const pz of [-1, 1]) box(g, px, 0, pz, .12, 3.25, .12, mats.wood);
  box(g, 0, 3.2, 0, 5, .15, 2.9, mats.trim);
  for (let i = 0; i < 6; i++) box(g, -2.05 + i * .82, 3.3, 0, .83, .12, 2.95, i % 2 ? mats.wallLight : mat(color), false);
  for (let i = -2; i <= 2; i++) {
    const sack = sphere(g, i * .58, 1.45, -1.42, .3, i % 2 ? mats.teal : mats.red, .75); sack.rotation.x = .18;
  }
}
makeStall(-20, 10, '#c6a567', .16); makeStall(-33, -2, '#4d7b78', -.25);
makeStall(20, -8, '#b4533d', -.2); makeStall(34, -18, '#d1b879', .28);
makeStall(-12, -34, '#426b73', .2);

// Memory fragments sparkle above small stone plinths. E collects them.
const fragments = [
  { x: -27, z: 11, title: 'The courier’s ledger', note: 'A name is written in two hands — one Brotherhood, one Templar.' },
  { x: 27, z: -11, title: 'The broken seal', note: 'The envoy’s seal bears a crescent cut through the cross: a warning, not a threat.' },
  { x: -11, z: -44, title: 'The old oath', note: 'Layla’s mentor left one final line: “Peace is not inherited. It is chosen.”' },
].map((item, index) => {
  const g = makeGroup(item.x, item.z);
  cylinder(g, 0, 0, 0, .8, .36, mats.trim, 8);
  cylinder(g, 0, .36, 0, .58, .18, mats.gold, 8);
  const crystal = new THREE.Mesh(new THREE.OctahedronGeometry(.42, 0), mats.emissive);
  crystal.position.y = 1.12; crystal.castShadow = true; g.add(crystal);
  const halo = new THREE.Mesh(new THREE.TorusGeometry(.78, .025, 6, 32), mats.gold); halo.rotation.x = Math.PI / 2; halo.position.y = .65; g.add(halo);
  const light = new THREE.PointLight('#ffd178', 4.5, 7); light.position.y = 1.5; g.add(light);
  interactives.push({ ...item, type: 'fragment', group: g, object: crystal, index, found: false });
  return g;
});
const destination = { x: 0, z: -66, type: 'exit', title: 'Reach the Silent Minaret' };
const exitMarker = new THREE.Group(); exitMarker.position.set(destination.x, 0, destination.z); scene.add(exitMarker);
const exitRing = new THREE.Mesh(new THREE.TorusGeometry(1.05, .06, 8, 36), mats.gold); exitRing.rotation.x = Math.PI / 2; exitRing.position.y = .15; exitMarker.add(exitRing);
const exitBeam = new THREE.Mesh(new THREE.CylinderGeometry(.025, .48, 5.5, 12, 1, true), new THREE.MeshBasicMaterial({ color: '#ffce80', transparent: true, opacity: .14, side: THREE.DoubleSide })); exitBeam.position.y = 2.75; exitMarker.add(exitBeam);
interactives.push({ ...destination, group: exitMarker, type: 'exit' });

function makeActor(kind, x, z, colorAccent = mats.gold) {
  const root = new THREE.Group(); root.position.set(x, 0, z); scene.add(root);
  const torso = new THREE.Group(); torso.position.y = .82; root.add(torso);
  const tunicMat = kind === 'player' ? mats.robe : mat('#d4c8ad');
  const tunic = new THREE.Mesh(new THREE.CylinderGeometry(.28, .4, 1.05, 10), tunicMat); tunic.position.y = .04; tunic.castShadow = true; torso.add(tunic);
  const chest = new THREE.Mesh(new THREE.BoxGeometry(.61, .52, .34), kind === 'player' ? mats.cloth : mats.wallLight); chest.position.set(0, .35, -.01); chest.castShadow = true; torso.add(chest);
  const belt = new THREE.Mesh(new THREE.CylinderGeometry(.325, .34, .095, 10), mats.gold); belt.position.y = -.12; torso.add(belt);
  const head = new THREE.Group(); head.position.y = .78; torso.add(head);
  sphere(head, 0, 0, 0, .23, mats.skin, 1.1);
  if (kind === 'player') {
    sphere(head, 0, .06, -.1, .265, mats.cloth, .9);
    const veil = new THREE.Mesh(new THREE.CylinderGeometry(.22, .29, .42, 12, 1, true), mats.cloth); veil.position.set(0, -.05, .025); head.add(veil);
    const scarf = box(torso, 0, .45, .2, .14, .92, .09, mats.gold); scarf.rotation.z = -.1;
    box(torso, -.16, -.25, -.04, .16, .6, .16, mats.red).rotation.z = -.1;
    const insignia = new THREE.Mesh(new THREE.TorusGeometry(.09, .018, 6, 16, Math.PI * 1.5), mats.gold); insignia.position.set(0, .38, .19); torso.add(insignia);
  } else {
    const hood = new THREE.Mesh(new THREE.ConeGeometry(.29, .48, 10), mats.red); hood.position.y = .12; head.add(hood);
    const cross = box(torso, .12, .43, .19, .075, .38, .035, mats.red); cross.rotation.z = .1;
    box(torso, .12, .45, .19, .23, .065, .04, mats.red);
  }
  const limbs = [];
  for (const side of [-1, 1]) {
    const arm = new THREE.Group(); arm.position.set(side * .38, .63, 0); torso.add(arm);
    const sleeve = new THREE.Mesh(new THREE.CylinderGeometry(.115, .14, .66, 8), kind === 'player' ? mats.cloth : mats.wallLight); sleeve.position.y = -.2; sleeve.rotation.z = side * -.13; arm.add(sleeve);
    sphere(arm, 0, -.55, .02, .11, mats.skin);
    const leg = new THREE.Group(); leg.position.set(side * .2, .25, 0); root.add(leg);
    const pants = new THREE.Mesh(new THREE.CylinderGeometry(.14, .12, .62, 8), kind === 'player' ? mats.black : mats.dark); pants.position.y = -.22; leg.add(pants);
    const shoe = box(leg, 0, -.54, -.08, .27, .14, .4, mats.wood); shoe.castShadow = true;
    limbs.push({ arm, leg, side });
  }
  if (kind === 'player') {
    const cape = box(torso, 0, -.01, .28, .53, .92, .13, mats.cloth); cape.rotation.x = -.12;
  } else {
    const shield = box(torso, -.4, .08, .02, .16, .48, .37, mats.wood); shield.rotation.z = -.12;
    const mark = box(torso, -.4, .1, .22, .06, .27, .035, mats.red);
    box(torso, -.4, .1, .22, .18, .05, .04, mats.red);
  }
  return { root, torso, limbs, phase: rand() * 6.28, kind };
}
const player = makeActor('player', 0, 18);
player.root.rotation.y = Math.PI;
const guardDefs = [
  { x: -27, z: 5, route: [[-27, 5], [-34, 3], [-34, 18], [-22, 18]] },
  { x: 27, z: -5, route: [[27, -5], [34, -2], [34, -19], [21, -19]] },
  { x: -8, z: -43, route: [[-8, -43], [-18, -38], [-18, -52], [-4, -54]] },
  { x: 7, z: -70, route: [[7, -70], [11, -66], [-10, -66], [-8, -73]] },
];
for (const def of guardDefs) {
  const actor = makeActor('guard', def.x, def.z);
  guards.push({ ...def, actor, routeIndex: 1, alert: 0, cooldown: 0, phase: rand() * 5 });
}

// UI state and friendly, story-first interaction prompts.
const $ = (s) => document.querySelector(s);
const toast = $('#toast'), interaction = $('#interaction'), interactionText = $('#interaction-text');
const keys = new Set();
const state = { started: false, paused: false, crouched: false, jumping: false, vy: 0, collected: 0, complete: false, yaw: Math.PI, pitch: .19, suspicion: 0, toastTimer: 0, lastTime: 0, elapsed: 0, active: null, sound: false, ending: false };
function announce(text, duration = 2600) { toast.textContent = text; toast.classList.add('show'); state.toastTimer = duration / 1000; }
function setCollected() {
  $('#fragment-count').textContent = `${state.collected} / 3`;
  $('#progress-fill').style.width = `${state.collected / 3 * 100}%`;
  if (state.collected < 3) $('#objective-text').textContent = state.collected === 0 ? 'Recover the courier’s ledger' : 'Find the remaining memory fragments';
  else $('#objective-text').textContent = 'Reach the Silent Minaret';
}
function nearestInteraction() {
  let nearest = null, distBest = 3.2;
  for (const item of interactives) {
    if (item.type === 'fragment' && item.found) continue;
    if (item.type === 'exit' && state.collected < 3) continue;
    const d = Math.hypot(player.root.position.x - item.x, player.root.position.z - item.z);
    if (d < distBest) { nearest = item; distBest = d; }
  }
  state.active = nearest;
  interaction.classList.toggle('visible', !!nearest && state.started && !state.ending);
  if (nearest) interactionText.textContent = nearest.type === 'exit' ? 'Enter the minaret' : `Take ${nearest.title.toLowerCase()}`;
}
function interact() {
  const item = state.active; if (!item) return;
  if (item.type === 'fragment') {
    item.found = true; item.group.visible = false; state.collected++; setCollected(); announce(`${item.title.toUpperCase()} — ${item.note}`, 4200);
    if (state.collected === 3) { announce('ALL THREE MEMORIES FOUND · THE MINARET AWAITS', 3600); exitMarker.visible = true; }
  } else if (item.type === 'exit') finishSequence();
}
function finishSequence() {
  state.ending = true; state.started = false; interaction.classList.remove('visible'); $('#ending').classList.remove('hidden');
  $('#ending-copy').textContent = 'Layla reaches the lantern room. The evidence could expose the envoy’s plan — or the old oath could keep the city from a new cycle of revenge. What will she carry into the dawn?';
  document.exitPointerLock?.();
}
$('#reveal-choice').addEventListener('click', () => {
  $('#ending-copy').textContent = 'Layla carries the evidence into the open. The truth is shared with both sides, and Qamar’s people demand a truce in their own names — not in the name of any order.';
  $('#reveal-choice').classList.add('selected'); $('#seal-choice').classList.remove('selected');
});
$('#seal-choice').addEventListener('click', () => {
  $('#ending-copy').textContent = 'Layla seals the evidence beside the old oath. The envoy leaves without a battle, and the secret rests with those who must choose peace again tomorrow.';
