      const forwardX = Math.sin(guard.actor.root.rotation.y), forwardZ = -Math.cos(guard.actor.root.rotation.y);
      sees = (dx * forwardX + dz * forwardZ) / dist > .48;
    }
    if (sees) guard.alert = Math.min(1, guard.alert + dt * (dist < 7 ? .38 : .2));
    else guard.alert = Math.max(0, guard.alert - dt * .16);
    if (guard.alert > .62 && guard.cooldown <= 0) {
      guard.cooldown = 7; guard.alert = .42; announce('A TEMPLAR HAS SPOTTED YOU · BREAK THE LINE OF SIGHT', 2400);
    }
    highest = Math.max(highest, guard.alert);
    const target = guard.route[guard.routeIndex];
    const tx = target[0] - p.x, tz = target[1] - p.z, td = Math.hypot(tx, tz);
    if (td < 1.3) guard.routeIndex = (guard.routeIndex + 1) % guard.route.length;
    else if (guard.cooldown <= 6.3 && !sees) {
      const speed = 1.2;
      p.x += tx / td * speed * dt; p.z += tz / td * speed * dt;
      guard.actor.root.rotation.y = Math.atan2(tx, -tz);
    }
    guard.actor.phase += dt * (td > 1.4 ? 3.4 : 1.2);
