const $=s=>document.querySelector(s),intro=$('#intro'),ending=$('#ending'),toast=$('#toast'),interaction=$('#interaction'),interactionText=$('#interaction-text');
const keys=new Set(),moveTouch={forward:false,back:false,left:false,right:false};let started=false,finished=false,crouched=false,sprinting=false,muted=true,toastTimer=0,yaw=0,pitch=.12,nearest=null,alertLevel=0,lastTime=0;
const playerPos=player.position,velocity=new THREE.Vector3(),cameraTarget=new THREE.Vector3(),cameraPos=new THREE.Vector3();
const objective=$('#objective-text'),countEl=$('#fragment-count'),progress=$('#progress-fill'),stealthText=$('#stealth-text');
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}
function updateObjective(){const n=fragments.filter(f=>f.found).length;countEl.textContent=`${n} / 3`;progress.style.width=`${n/3*100}%`;if(n<3)objective.textContent=`Recover the ${['courier’s ledger','witness’s account','hidden letter'][n]}`;else{objective.textContent='Reach the silent minaret';showToast('All clues recovered · Reach the minaret')}}
function near(a,b,dist){return Math.hypot(a.x-b.x,a.z-b.z)<dist}
function interact(){if(!started||finished)return;if(nearest?.type==='fragment'){const f=nearest.data;if(f.found)return;f.found=true;f.group.visible=false;showToast(`${f.spot.title} — ${f.spot.copy}`);updateObjective();return}if(nearest?.type==='tower'&&fragments.every(f=>f.found)){finished=true;$('#ending-copy').textContent='The envoy waits beneath the minaret. The fragments reveal that the Brotherhood and the Order were both deceived by a third hand. What will Layla do with the truth?';ending.classList.remove('hidden');if(document.pointerLockElement)document.exitPointerLock();return}if(nearest?.type==='guard'){showToast('Keep your distance. The sentry watches the alleys.');return}showToast(fragments.some(f=>!f.found)?'The envoy is near the minaret. Find all three clues first.':'The minaret is close. Press E to finish the memory.')}
function updateNearest(){nearest=null;let best=2.7;for(const f of fragments)if(!f.found){const d=Math.hypot(playerPos.x-f.spot.x,playerPos.z-f.spot.z);if(d<best){best=d;nearest={type:'fragment',data:f}}}const dt=Math.hypot(playerPos.x,playerPos.z+77);if(dt<best&&fragments.every(f=>f.found)){best=dt;nearest={type:'tower'}}for(const q of guardsData){const d=Math.hypot(playerPos.x-q.x,playerPos.z-q.z);if(d<best){best=d;nearest={type:'guard'}}}interaction.classList.toggle('visible',!!nearest);interactionText.textContent=nearest?.type==='fragment'?'Recover memory fragment':nearest?.type==='tower'?'Enter the minaret':nearest?.type==='guard'?'Observe sentry':'Examine'}
function collides(x,z){if(Math.abs(x)>108||Math.abs(z)>108)return true;for(const c of colliders){if(Math.abs(x-c.x)<c.w/2+.38&&Math.abs(z-c.z)<c.d/2+.38)return true}return false}
function moveAxis(dx,dz){const nx=playerPos.x+dx,nz=playerPos.z+dz;if(!collides(nx,playerPos.z))playerPos.x=nx;if(!collides(playerPos.x,nz))playerPos.z=nz}
function triggerEnding(choice){$('#ending-copy').textContent=choice==='reveal'?'Layla shares the evidence with the city. The envoy’s deception is exposed, and old rivals begin a fragile conversation. The truth is no longer hers alone.':'Layla seals the fragments inside the minaret. The city is spared a sudden reckoning, but the burden of the truth remains with her. The oath endures—for now.';$('#reveal-choice').classList.toggle('chosen',choice==='reveal');$('#seal-choice').classList.toggle('chosen',choice==='seal');$('#replay-button').classList.add('ready')}
$('#reveal-choice').addEventListener('click',()=>triggerEnding('reveal'));$('#seal-choice').addEventListener('click',()=>triggerEnding('seal'));
$('#begin-button').addEventListener('click',()=>{started=true;intro.classList.add('hidden');canvas.requestPointerLock?.();showToast('The old quarter · Find the courier’s three clues')});$('#replay-button').addEventListener('click',()=>location.reload());$('#sound-toggle').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♪':'♫';showToast(muted?'Sound muted':'Ambient sound enabled')});
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===canvas)document.body.classList.add('locked');else document.body.classList.remove('locked')});canvas.addEventListener('click',()=>{if(started&&!finished&&!document.pointerLockElement)canvas.requestPointerLock?.()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0018,-.25,.62)}});
document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='KeyE'&&!e.repeat)interact();if(e.code==='KeyC'&&!e.repeat)crouched=!crouched;if(e.code==='Escape'&&started)showToast('Click the world to resume')});document.addEventListener('keyup',e=>keys.delete(e.code));
document.querySelectorAll('[data-move]').forEach(btn=>{const dir=btn.dataset.move;btn.addEventListener('pointerdown',e=>{e.preventDefault();moveTouch[dir]=true;btn.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,()=>moveTouch[dir]=false))});$('#touch-jump').addEventListener('pointerdown',()=>{velocity.y=5.5});$('#touch-crouch').addEventListener('click',()=>crouched=!crouched);$('#touch-use').addEventListener('click',interact);
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}addEventListener('resize',resize);
function update(dt,time){for(const f of fragments){f.crystal.rotation.y=time*.8+f.phase;f.crystal.position.y=.9+Math.sin(time*2+f.phase)*.13;f.group.rotation.y=time*.25}
 if(started&&!finished){const fw=keys.has('KeyW')||keys.has('ArrowUp')||moveTouch.forward,bk=keys.has('KeyS')||keys.has('ArrowDown')||moveTouch.back,lt=keys.has('KeyA')||keys.has('ArrowLeft')||moveTouch.left,rt=keys.has('KeyD')||keys.has('ArrowRight')||moveTouch.right;let forward=Number(fw)-Number(bk),side=Number(rt)-Number(lt);const mag=Math.hypot(forward,side)||1;forward/=mag;side/=mag;sprinting=(keys.has('ShiftLeft')||keys.has('ShiftRight'))&&!crouched;const speed=crouched?2.05:sprinting?7.2:4.15;const dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*side)*speed*dt,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*side)*speed*dt;moveAxis(dx,dz);player.rotation.y=yaw;player.scale.y=crouched?.78:1;player.position.y=crouched?-.22:0;
 let threat=0;guardsData.forEach((q,i)=>{const gd=guards[i],t=time*.46+gd.phase;const px=gd.home.x+Math.sin(t)*5.5,pz=gd.home.z+Math.cos(t*.8)*4;gd.group.position.set(px,0,pz);gd.group.rotation.y=Math.atan2(gd.home.x-px,gd.home.z-pz);const d=Math.hypot(playerPos.x-px,playerPos.z-pz);const inSight=d< (crouched?4.1:8.5)&&Math.abs(playerPos.y)<1;if(inSight)threat=Math.max(threat,clamp((crouched?4.1:8.5-d)/(crouched?4.1:8.5),0,1));});alertLevel=THREE.MathUtils.damp(alertLevel,threat,threat?2.8:1.2,dt);stealthText.textContent=alertLevel>.72?'SPOTTED':alertLevel>.2?'SUSPICIOUS':crouched?'HIDDEN':'UNSEEN';document.querySelectorAll('.alert-meter i').forEach((el,i)=>{el.classList.toggle('on',alertLevel>(i+1)*.25);el.classList.toggle('danger',alertLevel>.72)});if(alertLevel>.88){showToast('A sentry has spotted you · Break line of sight');alertLevel=.48}
 updateNearest();}
 const targetDistance=6.8;cameraTarget.set(playerPos.x,playerPos.y+1.25,playerPos.z);cameraPos.set(playerPos.x+Math.sin(yaw)*targetDistance,playerPos.y+2.55+pitch*3,playerPos.z+Math.cos(yaw)*targetDistance);camera.position.lerp(cameraPos,1-Math.exp(-dt*7));camera.lookAt(cameraTarget);
}
function animate(now){requestAnimationFrame(animate);const time=now/1000,dt=Math.min(.04,lastTime?time-lastTime:0);lastTime=time;update(dt,time);renderer.render(scene,camera)}
$('#loading').classList.add('done');setTimeout(()=>$('#loading').remove(),650);requestAnimationFrame(animate);

